const ZIP_BASE64 = "";
export function backendZipResponse() {
  return new Response(Uint8Array.from(atob(ZIP_BASE64), (c) => c.charCodeAt(0)), {
    headers: {
      'content-type': 'application/zip',
      'content-disposition': 'attachment; filename="jbackend-main-wired.zip"',
      'cache-control': 'no-store',
    },
  });
}
